/* Read-only fixed-clock sphere; every disk uses the same real collision radius. */
static void orb87_disk(float x,float y,float r,SDL_FColor c){for(int i=0;i<24;i++){float a=i*PI/12,b=(i+1)*PI/12;int first=nquad;quad(0,0,1,1,c,.5f,.5f,0,0);if(nquad==first)return;SDL_FPoint p[4]={{x*3,y*3},{(x+cosf(a)*r)*3,(y+sinf(a)*r)*3},{(x+cosf(b)*r)*3,(y+sinf(b)*r)*3},{x*3,y*3}};for(int v=0;v<4;v++){vertices[first*4+v].position=p[v];vertices[first*4+v].tex_coord=(SDL_FPoint){.5f,.5f};if(v==1||v==2)vertices[first*4+v].color.a=0;}}}
static void orb87_draw(const Obj*s){float x=s->x/(float)Q,y=s->y/(float)Q,r=orb87_radius(s),fade=s->orbFade87?s->orbFade87/(float)ORB87_FADE:1,phase=reducedMotion?0:visualTick*.045f+s->serial*.7f;for(int i=0;i<32;i++){float a=i*PI/16,b=(i+1)*PI/16;beam_ribbon(x+cosf(a)*r,y+sinf(a)*r,x+cosf(b)*r,y+sinf(b)*r,.18f,(SDL_FColor){.35f,.9f,1,.26f*fade});}light(x,y,r*1.3f,.2f,.75f,1,.13f*fade);orb87_disk(x,y,r,(SDL_FColor){.08f,.68f,1,.12f*fade});orb87_disk(x-r*.16f,y-r*.16f,r*.68f,(SDL_FColor){.48f,.94f,1,.24f*fade});orb87_disk(x-r*.24f,y-r*.24f,r*.30f,(SDL_FColor){.93f,1,1,.6f*fade});for(int i=0;i<12;i++){float a=i*PI/6+phase,xx=x+cosf(a)*r*.86f,yy=y+sinf(a)*r*.86f;beam_ribbon(xx,yy,x+cosf(a+.20f)*r*.82f,y+sinf(a+.20f)*r*.82f,fmaxf(.14f,r*.012f),(SDL_FColor){1,.64f,.25f,.32f*fade});}light(x,y,r*.4f,.7f,1,1,.3f*fade);}
